function setComparison(prefix,value,base){const kpi=document.querySelector('#'+prefix+'Kpi'),label=document.querySelector('#'+prefix+'Label');if(!kpi||!label)return;kpi.className='';if(value===null||value===undefined){kpi.textContent='—';label.textContent='Sem histórico comparável';return}kpi.textContent=`${value>=0?'▲':'▼'} ${Math.abs(value).toFixed(1)}%`;kpi.classList.add(value>=0?'positive':'negative');label.textContent=`Base ${money(base||0)}`}
