function renderAnalytics(){const q=document.querySelector('#analyticSearch').value.trim().toLowerCase(),company=document.querySelector('#analyticCompany').value,canal=document.querySelector('#analyticChannel').value,filtered=analyticData.filter(x=>(company==='all'||x.empresa===company)&&(canal==='all'||x.canal===canal)&&(!q||[x.pedido,x.empresa,x.canal,x.modalidade,x.marcadores,x.ecommerce,x.situacao].some(v=>String(v).toLowerCase().includes(q))));document.querySelector('#analyticOrders').textContent=new Intl.NumberFormat('pt-BR').format(analyticData.length);document.querySelector('#analyticGmv').textContent=money(analyticData.filter(x=>x.contabilizado).reduce((s,x)=>s+(+x.valor||0),0));document.querySelector('#analyticComplete').textContent=(analyticData.length?analyticData.filter(x=>x.detalhe==='Completo').length/analyticData.length*100:0).toFixed(0)+'%';const page=pageRows(filtered,'analytic');document.querySelector('#analyticsRows').innerHTML=filtered.length?page.rows.map(x=>`<tr><td><b>${x.pedido}</b></td><td>${x.empresa}</td><td><span class="channel-pill ${x.canal==='A identificar'?'warning':''}">${x.canal}</span></td><td><span class="mode-pill ${x.modalidade!=='Convencional'?'full':''}" title="${x.marcadores||''}">${x.modalidade||'Convencional'}</span></td><td>${x.ecommerce}</td><td>${x.situacao}</td><td class="${x.detalhe==='Completo'?'detail-complete':'detail-pending'}">${x.detalhe}</td><td>${fullMoney(x.valor)}</td></tr>`).join(''):'<tr><td colspan="8" class="empty-table">Nenhum pedido encontrado com os filtros selecionados.</td></tr>'}
function setupAnalytics(payload){analyticData=payload.analytics||[];management=payload.management||[];streamingStatus=payload.streaming||{};operational=payload.operational||{};const options=[...new Set(analyticData.map(x=>x.canal))].sort(),companies=[...new Set(['Oficial','Prioriza','OFICIALSP','OFICIALSP2',...(payload.accounts||[]).map(x=>x.empresa),...analyticData.map(x=>x.empresa)])].filter(Boolean).sort(),unidentified=payload.diagnostics?.unidentified||[],alert=document.querySelector('#dataQualityAlert');alert.hidden=!unidentified.length;alert.innerHTML=unidentified.length?`<strong>ATENÇÃO DE QUALIDADE</strong><span>${unidentified.length} pedido(s) ainda sem canal identificado. Eles permanecem visíveis para conciliação e não são ocultados.</span>`:'';const savedCompany=document.querySelector('#analyticCompany').value,savedChannel=document.querySelector('#analyticChannel').value;document.querySelector('#analyticChannel').innerHTML='<option value="all">Todos os canais</option>'+options.map(x=>`<option>${x}</option>`).join('');document.querySelector('#analyticCompany').innerHTML='<option value="all">Todas as empresas</option>'+companies.map(x=>`<option>${x}</option>`).join('');document.querySelector('#analyticCompany').value=companies.includes(savedCompany)?savedCompany:'all';document.querySelector('#analyticChannel').value=options.includes(savedChannel)?savedChannel:'all';renderManagement();renderOperational();renderAnalytics()}
async function loadBigQuery(update=false){const endpoint=update?'/api/update-data':`/api/data?date=${encodeURIComponent(selectedDate||'')}`;try{const response=await fetch(endpoint,{cache:'no-store'});if(!response.ok)throw new Error((await response.json()).error||'Falha na atualização');const raw=await response.json(),payload=DASHBOARD_DATA.normalize(raw),reconciliation=payload.reconciliation||{},retrying=reconciliation.status==='retrying';todayDate=payload.today||new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());selectedDate=payload.dataDate||selectedDate||todayDate;const picker=document.querySelector('#dashboardDate');picker.value=selectedDate;picker.max=todayDate;document.body.classList.toggle('historical-mode',Boolean(payload.isHistorical));comparisons=payload.comparisons||{};executiveReport=payload;financialReport=DASHBOARD_DATA.normalize(FINANCIAL_REPORT.fromPayload(raw));dailyTarget=Number(payload.target||0);dailyGoalReached=payload.goalReachedAt||DASHBOARD_DATA.goalState(payload.snapshotHistory||[],dailyTarget,selectedDate).reachedAt;isUpdating=Boolean(payload.updating)||reconciliation.status==='updating';document.querySelector('#updateStatus').classList.toggle('syncing',isUpdating||retrying);document.querySelector('#statusLabel').textContent=payload.isHistorical?'FECHAMENTO HISTÓRICO':retrying?`RECONCILIANDO ${reconciliation.pending||''} PEDIDOS`:isUpdating?'ATUALIZANDO EVENTOS':'ÚLTIMA ATUALIZAÇÃO';setupAnalytics(payload);snapshotHistory=payload.snapshotHistory||[];perspectiveViews=payload.views||[];baseLiveMetrics=payload.metrics||{};liveMetrics={...baseLiveMetrics};if(selectedDate===todayDate){const key='bf-chart-baseline-v3-'+selectedDate;try{chartBaseline=JSON.parse(localStorage.getItem(key)||'null')}catch{chartBaseline=null}if(!chartBaseline){const hour=Number(baseLiveMetrics.activeHour||new Date().getHours()),scopes={};for(const view of perspectiveViews)scopes[view.scope]={...(view.currentChannels||{})};chartBaseline={hour,createdAt:payload.updatedAt,scopes};localStorage.setItem(key,JSON.stringify(chartBaseline))}}else chartBaseline=null;applyReportPayload();if(payload.updatedAt)document.querySelector('#lastUpdate').textContent=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(payload.updatedAt));if(update&&payload.waitingForLoad)toast('A primeira carga de hoje ainda não saiu');return true}catch(error){if(update)toast('Tiny: '+error.message);return false}}
async function waitHistoricalReconciliation(date){
  while(true){
    await new Promise(resolve=>setTimeout(resolve,2000));
    const response=await fetch('/api/data?date='+encodeURIComponent(date),{cache:'no-store'});
    if(!response.ok)throw new Error('Falha ao consultar a reconciliação');
    const payload=await response.json(),job=payload.historicalReconciliation;
    if(!job)throw new Error('Reconciliação interrompida. Atualize novamente.');
    if(job.status==='failed')throw new Error(job.error||'Falha na reconciliação');
    if(job.status==='completed')return;
  }
}
document.querySelector('#refreshBtn').addEventListener('click',async e=>{e.currentTarget.classList.add('loading');try{const date=selectedDate||todayDate||'';const response=await fetch(`/api/update-data?date=${encodeURIComponent(date)}&background=1`,{cache:'no-store'});if(!response.ok)throw new Error((await response.json()).error||'Falha na reconciliação');if(response.status===202)await waitHistoricalReconciliation(date);await loadBigQuery(false);toast(`Tiny reconciliado para ${date.split('-').reverse().join('/')}`)}catch(error){toast('Tiny: '+error.message)}finally{e.currentTarget.classList.remove('loading')}});
document.querySelector('#dashboardDate').addEventListener('change',async e=>{selectedDate=e.target.value;await loadBigQuery(false)});
document.querySelector('#channelFilter').innerHTML+=[...channels].map(c=>`<option>${c.name}</option>`).join('');document.querySelector('#channelFilter').addEventListener('change',e=>{activeChannel=e.target.value==='all'?'all':e.target.value;renderChart()});
document.querySelectorAll('.view-tab').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.view-tab,.report-view').forEach(x=>x.classList.remove('active'));button.classList.add('active');document.querySelector('#'+button.dataset.view).classList.add('active');if(button.dataset.view==='dashboardView')setReport(button.dataset.report||'executive')}));document.querySelector('#analyticSearch').addEventListener('input',renderAnalytics);document.querySelector('#analyticCompany').addEventListener('change',renderAnalytics);document.querySelector('#analyticChannel').addEventListener('change',renderAnalytics);
document.querySelector('#fileInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text(),lines=text.trim().split(/\r?\n/),sep=lines[0].includes(';')?';':',',head=lines.shift().split(sep).map(x=>x.trim().toLowerCase()),ci=head.findIndex(x=>['canal','channel'].includes(x)),hi=head.findIndex(x=>['hora','hour'].includes(x)),vi=head.findIndex(x=>['gmv','valor','value'].includes(x));if([ci,hi,vi].some(x=>x<0))throw Error();const map={};lines.forEach(l=>{const p=l.split(sep),name=p[ci].trim(),hour=p[hi].trim(),value=Number(p[vi].replace(/[^0-9,.-]/g,'').replace('.','').replace(',','.'));if(!map[name])map[name]={};map[name][hour]= (map[name][hour]||0)+value});const newHours=[...new Set(lines.map(l=>l.split(sep)[hi].trim()))];hours.splice(0,hours.length,...newHours);data=Object.entries(map).map(([channel,obj])=>({channel,hours:newHours.map(hour=>({hour,value:obj[hour]||0}))}));activeChannel='all';document.querySelector('#channelFilter').innerHTML='<option value="all">Todos os canais</option>'+data.map(d=>`<option>${d.channel}</option>`).join('');render();stamp();toast(`${data.length} canais importados com sucesso`)}catch{toast('CSV inválido. Use as colunas: hora, canal, gmv')}});
setInterval(()=>{const now=new Date(),e=document.querySelector('#liveClock');if(e)e.textContent=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(now);const date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);if(todayDate&&date!==todayDate&&selectedDate===todayDate){selectedDate=date;loadBigQuery(false)}},1000);setInterval(()=>loadBigQuery(false),60000);try{const stream=new EventSource('/api/events');stream.onmessage=()=>{if(selectedDate===todayDate)loadBigQuery(false)}}catch{}stamp();render();loadBigQuery(false);
try{const historicalStream=new EventSource('/api/events');historicalStream.onmessage=event=>{try{const message=JSON.parse(event.data);if(message.dataDate===selectedDate&&selectedDate!==todayDate)loadBigQuery(false)}catch{}}}catch{}

function chartHourLimit(){const now=new Date(),today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);return selectedDate&&selectedDate<today?23:Number(new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',hour:'2-digit',hour12:false}).format(now))}
function pageRows(rows,type){const root=document.documentElement,mobile=(root?.clientWidth||1280)<=760,height=root?.clientHeight||900,size=type==='analytic'?(mobile?Math.max(1,Math.floor((height-340)/210)):Math.max(1,Math.floor((height-300)/38))):Math.max(1,Math.floor((document.querySelector('#ranking')?.clientHeight||height-(mobile?235:430))/44));const pages=Math.max(1,Math.ceil(rows.length/size)),page=Math.min(pageState[type]||0,pages-1);pageState[type]=page;const prev=document.querySelector('#'+type+'Prev'),next=document.querySelector('#'+type+'Next');prev.disabled=page===0;next.disabled=page===pages-1;document.querySelector('#'+type+'PageLabel').textContent=(page+1)+' / '+pages+' • '+rows.length+' '+(type==='rank'?'canais':'pedidos');return {rows:rows.slice(page*size,(page+1)*size),start:page*size}}

document.querySelectorAll('.scope-button').forEach(button=>button.addEventListener('click',()=>{pageState.rank=0;applyScope(button.dataset.scope)}));
document.querySelectorAll('[data-panel]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#dashboardView').dataset.mobilePanel=button.dataset.panel;document.querySelectorAll('[data-panel]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));if(lastRanking.length)renderRanking(lastRanking,lastRankingTotal);renderChart()}));
for(const type of ['rank','analytic'])for(const [suffix,delta] of [['Prev',-1],['Next',1]])document.querySelector('#'+type+suffix).addEventListener('click',()=>{pageState[type]=Math.max(0,pageState[type]+delta);if(type==='rank')renderRanking(lastRanking,lastRankingTotal);else renderAnalytics()});
if(typeof window!=='undefined')window.addEventListener('resize',()=>{if(lastRanking.length)renderRanking(lastRanking,lastRankingTotal);renderAnalytics();renderChart()});

function showHourValue(hour){
  if(!Number.isInteger(hour)||hour<0||hour>=hours.length||hour>chartHourLimit())return;
  selectedChartHour=hour;
  const rows=activeChannel==='all'?data:data.filter(row=>row.channel===activeChannel);
  const value=rows.reduce((sum,row)=>sum+Math.max(0,Number(row.hours[hour]?.value||0)),0);
  const formatted=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value);
  document.querySelector('#chartLegend').textContent=hours[hour]+' • '+activeScope+' • '+(activeChannel==='all'?'Todos os canais':activeChannel)+': '+formatted;
  document.querySelector('#chartLegend').setAttribute('aria-live','polite');
  document.querySelectorAll('#hourlyChart [data-hour-index]').forEach(bar=>bar.setAttribute('aria-pressed',String(Number(bar.dataset.hourIndex)===hour)));
  document.querySelector('#hourDetailsTitle').textContent=hours[hour]+' • '+activeScope;
  const format=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);
  const breakdown=rows.map(row=>({channel:row.channel,value:Math.max(0,Number(row.hours[hour]?.value||0))})).filter(row=>row.value>0).sort((a,b)=>b.value-a.value);
  document.querySelector('#hourDetailsValues').textContent='Total realizado: '+formatted+'\n\n'+(breakdown.length?breakdown.map(row=>row.channel+': '+format(row.value)).join('\n'):'Nenhuma venda nesta hora.');
  return true;
}
function activateHourBar(event){const bar=event.target.closest?.('[data-hour-index]');if(bar&&showHourValue(Number(bar.dataset.hourIndex))){const detail=document.querySelector('#hourDetails');if(!detail.open)detail.showModal()}}
document.querySelector('#hourlyChart').addEventListener('click',activateHourBar);
document.querySelector('#hourlyChart').addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();activateHourBar(event)}});
if(typeof ResizeObserver!=='undefined')new ResizeObserver(()=>{if(lastRanking.length)renderRanking(lastRanking,lastRankingTotal)}).observe(document.querySelector('#ranking'));

document.querySelector('#hourDetailsClose').addEventListener('click',()=>document.querySelector('#hourDetails').close());

function renderTotalDayComparison(total){
  const comparison=comparisons.byScope?.[activeScope] || perspectiveViews.find(view=>view.scope===activeScope)?.comparisons || (activeScope==='Consolidado'?comparisons:null);
  const rawBase=comparison?.previousDayGmv,base=rawBase===null||rawBase===undefined?null:Number(rawBase),element=document.querySelector('#totalDelta');
  const available=base!==null&&Number.isFinite(base)&&base>=0;
  const change=available&&base>0?(total/base-1)*100:null;
  element.textContent=!available?'Sem dados do dia anterior':base===0?'Dia anterior sem faturamento':`${change>0?'▲':change<0?'▼':'•'} ${Math.abs(change).toFixed(1)}% vs. dia anterior`;
  element.style.color=change===null||change===0?'var(--muted)':change>0?'var(--green)':'#ff6262';
  element.title=available?'Total registrado do dia anterior: '+fullMoney(base):'';
}

function applyReportPayload(){
  const payload=activeReport==='financial'?financialReport:executiveReport;
  if(!payload)return;
  snapshotHistory=payload.snapshotHistory||[];
  perspectiveViews=payload.views||[];
  baseLiveMetrics=payload.metrics||{};liveMetrics={...baseLiveMetrics};
  management=payload.management||[];comparisons=payload.comparisons||{};
  dailyTarget=Number(payload.target||0);
  dailyGoalReached=payload.goalReachedAt||DASHBOARD_DATA.goalState(snapshotHistory,dailyTarget,selectedDate).reachedAt;
  document.querySelector('#targetLabel').textContent=dailyTarget?money(dailyTarget):'SEM META';
  renderManagement();
  const reportHours=payload.series?.[0]?.hours?.map(point=>point.hour)||Array.from({length:24},(_,hour)=>String(hour).padStart(2,'0')+'h');
  hours.splice(0,hours.length,...reportHours);
  applyScope(perspectiveViews.some(view=>view.scope===activeScope)?activeScope:'Consolidado');
}
function setReport(report){
  activeReport=report==='financial'?'financial':'executive';selectedChartHour=null;pageState.rank=0;
  const detail=document.querySelector('#hourDetails');if(detail?.open)detail.close();
  applyReportPayload();renderFinancialDifference();
}
function renderFinancialDifference(){
  const element=document.querySelector('#financialDifference');
  element.hidden=activeReport==='financial';
  if(!executiveReport||!financialReport){element.textContent='Financeiro: aguardando dados';return;}
  const group=activeScope==='Full'?'Full Oficial':activeScope;
  const total=Number(executiveReport.management?.find(row=>row.grupo===group)?.gmv||0);
  const financial=Number(financialReport.management?.find(row=>row.grupo===group)?.gmv||0);
  const difference=total>0?(financial-total)/total*100:null;
  element.textContent=difference===null?'Financeiro: sem base de comparação':'Financeiro vs. executivo: '+(difference>0?'+':'')+difference.toFixed(1)+'%';
  element.title='GMV financeiro: '+fullMoney(financial)+' • GMV executivo: '+fullMoney(total);
}
